func TestConcurrentRenewalsInvoiceEachPeriodOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	var wg sync.WaitGroup
	var total atomic.Int64
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Error(err)
			}
			total.Add(int64(n))
		}()
	}
	wg.Wait()
	if total.Load() != 1 {
		t.Fatalf("renewed %d times, want once", total.Load())
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 {
		t.Fatalf("invoices = %d, want the first and one renewal", len(invs))
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want the first and one renewal", len(cs))
	}
}

func TestGatewayDownStillRenewsAndKeepsStatus(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
