95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
145	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
146	// due. RenewDue returns how many subscriptions it renewed or canceled.
147	//
148	// Each period is renewed once, however many RenewDue calls run at the same time or one after another: the store moves a
149	// subscription on only while it is still due. A charge the gateway could not take leaves its invoice open and the
150	// subscription keeps its status. RenewDue tries every subscription and returns the errors, joined, after the last one.
151	func (s *Service) RenewDue(ctx context.Context) (int, error) {
152		now := s.Clock.Now()
153		n := 0
154		var errs []error
155		for _, sub := range s.Store.DueSubscriptions(now) {
156			if err := ctx.Err(); err != nil {
157				return n, errors.Join(append(errs, err)...)
158			}
159			renewed, err := s.renew(ctx, sub, now)
160			if err != nil {
161				errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
162			}
163			if renewed {
164				n++
165			}
166		}
167		return n, errors.Join(errs...)
168	}
169	
170	// renew moves a due subscription on to its next period and invoices it. It reports false, and changes nothing, when another
171	// renewal already did so. Otherwise it reports true, even when the invoice could not be paid.
172	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
173		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
174		if !ok {
175			return false, store.ErrNotFound
176		}
177		due := sub.CurrentPeriodEnd
178		if sub.CancelAtPeriodEnd {
179			end := sub.CurrentPeriodEnd
180			canceled, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, due, now, func(x *store.Subscription) error {
181				x.Status, x.CanceledAt = store.Canceled, &end
182				return nil
183			})
184			if errors.Is(err, store.ErrNotDue) {
185				return false, nil
186			}
187			if err != nil {
188				return false, err
189			}
190			s.publish(ctx, canceled.OrgID, "subscription.canceled", canceled)
191			return true, nil
192		}
193		start := now
194		end := billing.AddInterval(start, plan.Interval)
195		// A licensed plan bills the new period in advance; a metered plan bills the period that ended, except during a trial.
196		billStart, billEnd, bill := start, end, plan.UsageType == store.Licensed
197		if plan.UsageType == store.Metered && sub.Status != store.Trialing {
198			billStart, billEnd, bill = sub.CurrentPeriodStart, sub.CurrentPeriodEnd, true
199		}
200		// Moving the period on comes before the charge, so a charge that fails or is slow cannot make the next run invoice again.
201		cur, err := s.Store.RenewSubscription(sub.OrgID, sub.ID, due, now, func(x *store.Subscription) error {
202			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
203			return nil
204		})
205		if errors.Is(err, store.ErrNotDue) {
206			return false, nil
207		}
208		if err != nil {
209			return false, err
210		}
211		paid := true
212		if bill {
213			paid, err = s.invoicePeriod(ctx, cur, plan, billStart, billEnd)
214			switch {
215			case errors.Is(err, payments.ErrUnavailable):
216				// Nothing was taken: the invoice stays open to be paid later, and the subscription keeps its status.
217				s.publish(ctx, cur.OrgID, "subscription.updated", cur)
218				return true, nil
219			case err != nil:
220				return true, err
221			}
222		}
223		cur, err = s.Store.UpdateSubscription(cur.OrgID, cur.ID, func(x *store.Subscription) error {
224			if paid {
225				x.Status = store.Active
226			} else {
227				x.Status = store.PastDue
228			}
229			return nil
230		})
231		if err != nil {
232			return true, err
233		}
234		s.publish(ctx, cur.OrgID, "subscription.updated", cur)
235		return true, nil
236	}
237	
238	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
239	// It reports false when the charge was declined, and wraps payments.ErrUnavailable when the gateway could not take it. An
240	// invoice that needs no charge is marked paid; one whose customer has no payment method stays open and counts as paid here
241	// (it is paid by hand).
242	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
243		var lines []store.Line
244		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
245		switch plan.UsageType {
246		case store.Licensed:
247			if plan.UnitAmount > 0 {
248				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
249			}
250		case store.Metered:
251			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
252				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
253			}
254		}
255		ps, pe := start, end
256		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
257			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
258		if err != nil {
259			return false, err
260		}
261		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
262		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
263		var decline *payments.DeclineError
264		switch {
265		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
266			return true, nil
267		case errors.As(err, &decline):
268			return false, nil
269		default:
270			return false, err
271		}
272	}
273	
274	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
275		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
276			x.Status = st
277			return nil
278		})
279		if err == nil {
280			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
281		}
282		return sub, err
283	}
