196	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
197	// canceled, the longest overdue first.
198	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
199		s.mu.Lock()
200		defer s.mu.Unlock()
201		out := []Subscription{}
202		for _, sub := range s.subs {
203			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
204				out = append(out, copySub(sub))
205			}
206		}
207		sort.Slice(out, func(i, j int) bool {
208			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
209				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
210			}
211			return out[i].ID < out[j].ID
212		})
213		return out
214	}
215	
216	func copySub(sub Subscription) Subscription {
217		if sub.TrialEnd != nil {
218			t := *sub.TrialEnd
219			sub.TrialEnd = &t
220		}
221		if sub.CanceledAt != nil {
222			t := *sub.CanceledAt
223			sub.CanceledAt = &t
224		}
225		return sub
226	}
