228	// AddUsage records usage of a subscription to a metered plan at time at.
229	func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
230		if quantity <= 0 {
231			return UsageRecord{}, invalid("usage must be a positive quantity")
232		}
233		s.mu.Lock()
234		defer s.mu.Unlock()
235		sub, ok := s.subs[subID]
236		if !ok || sub.OrgID != orgID {
237			return UsageRecord{}, ErrNotFound
238		}
239		if p := s.plans[sub.PlanID]; p.UsageType != Metered {
240			return UsageRecord{}, invalid("the subscription's plan is not metered")
241		}
242		u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
243		s.usage = append(s.usage, u)
244		return u, nil
245	}
