247	// UsageTotal adds up a subscription's usage at times in [from, to).
248	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
249		s.mu.Lock()
250		defer s.mu.Unlock()
251		var n int64
252		for _, u := range s.usage {
253			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
254				n += u.Quantity
255			}
256		}
257		return n
258	}
