262	// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
263	func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
264		if !inv.Currency.Valid() {
265			return Invoice{}, invalid("unknown currency %q", inv.Currency)
266		}
267		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
268			return Invoice{}, invalid("the discount is 0 to 100 percent")
269		}
270		for _, l := range inv.Lines {
271			if l.Quantity <= 0 {
272				return Invoice{}, invalid("a line needs a positive quantity")
273			}
274		}
275		s.mu.Lock()
276		defer s.mu.Unlock()
277		org, ok := s.orgs[inv.OrgID]
278		if !ok {
279			return Invoice{}, ErrNotFound
280		}
281		c, ok := s.customers[inv.CustomerID]
282		if !ok {
283			return Invoice{}, ErrNotFound
284		}
285		if c.OrgID != inv.OrgID {
286			return Invoice{}, ErrCustomerOrgMismatch
287		}
288		// A subscription's period is invoiced at most once: (subscription, period start) identifies its invoice.
289		if inv.SubscriptionID != "" && inv.PeriodStart != nil {
290			for _, other := range s.invoices {
291				if other.OrgID == inv.OrgID && other.SubscriptionID == inv.SubscriptionID && other.PeriodStart != nil && other.PeriodStart.Equal(*inv.PeriodStart) {
292					return Invoice{}, fmt.Errorf("%w: the subscription's period is already invoiced", ErrConflict)
293				}
294			}
295		}
296		inv.ID = s.newID("in")
297		inv.TaxRateBP = org.TaxRateBP
298		inv.Status = InvoiceOpen
299		inv.CreatedAt = now.UTC()
300		inv.PaidAt, inv.VoidedAt = nil, nil
301		inv = copyInvoice(inv)
302		s.invoices[inv.ID] = inv
303		return copyInvoice(inv), nil
304	}

