		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	var wg sync.WaitGroup
	var renewed atomic.Int64
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Error(err)
			}
			renewed.Add(int64(n))
		}()
	}
	wg.Wait()
	if renewed.Load() != 1 {
		t.Fatalf("renewed %d times, want once", renewed.Load())
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices = %d, want the first period and one renewal", len(invs))
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want the first period and one renewal", len(cs))
	}
}

func TestGatewayDownStillRenewsAndKeepsStatus(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	active, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	d := e.CreateCustomer(e.Acme, "Joe", "joe@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, d.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	pastDue, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: d.ID, PlanID: p.ID, Quantity: 1})
	if err != nil || pastDue.Status != store.PastDue {
		t.Fatalf("subscription = %+v, %v", pastDue, err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, d.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })

	e.Clock.Set(active.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 2 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	for _, want := range []struct {
		id     string
		status store.SubStatus
	}{{active.ID, store.Active}, {pastDue.ID, store.PastDue}} {
		got, _ := e.Store.Subscription(e.Acme.ID, want.id)
		if got.Status != want.status || !got.CurrentPeriodStart.Equal(e.Clock.Now()) {
			t.Fatalf("subscription = %+v, want status %s in the new period", got, want.status)
		}
	}
	if open := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{Status: store.InvoiceOpen}); len(open) != 3 {
		t.Fatalf("open invoices = %d, want the two renewals and the declined first period", len(open))
	}
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 0 {
		t.Fatalf("RenewDue again = %d, %v", n, err)
	}
	if n := countCharges(e.Gateway.Calls(), "pm_gateway_down"); n != 2 {
		t.Fatalf("the gateway was asked %d times, want once per subscription", n)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 4 {
		t.Fatalf("invoices = %d after a second run, want no new ones", len(invs))
	}
}

func countCharges(calls []payments.ChargeRequest, paymentMethod string) int {
	n := 0
	for _, c := range calls {
		if c.PaymentMethod == paymentMethod {
			n++
		}
	}
	return n
}

func TestRenewDueGoesOnPastAFailure(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	broken, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	healthy, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// An invoice already exists for the period the renewal would invoice, so creating the renewal's invoice fails.
	end := broken.CurrentPeriodEnd
	if _, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, SubscriptionID: broken.ID, Currency: money.USD,
		PeriodStart: &end, PeriodEnd: &end}, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(end)
	n, err := e.Subs.RenewDue(ctx)
	if !errors.Is(err, store.ErrConflict) || !strings.Contains(err.Error(), broken.ID) {
		t.Fatalf("RenewDue error = %v, want the broken subscription's conflict", err)
	}
	if n != 1 {
		t.Fatalf("RenewDue = %d, want the healthy subscription renewed and the broken one not", n)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, healthy.ID); !got.CurrentPeriodStart.Equal(e.Clock.Now()) {
		t.Fatalf("healthy subscription = %+v, not renewed", got)
	}
	// The broken subscription's period did not move, so it is still due and the next run tries it again.
	if got, _ := e.Store.Subscription(e.Acme.ID, broken.ID); !got.CurrentPeriodEnd.Equal(end) || !got.CurrentPeriodStart.Equal(broken.CurrentPeriodStart) {
		t.Fatalf("broken subscription = %+v, moved without its invoice", got)
	}
	if n, err := e.Subs.RenewDue(ctx); !errors.Is(err, store.ErrConflict) || n != 0 {
		t.Fatalf("RenewDue again = %d, %v, want the broken subscription tried and failing again", n, err)
	}
}

