// RenewSubscriptionInvoicedOnce is RenewSubscriptionInvoiced for a period that may already be invoiced. When the invoice for
// inv's period exists already, the subscription still moves on, nothing is stored, and the existing invoice is returned with
// created false: the period was invoiced once, and the caller must not charge it again. Otherwise it stores inv like
// RenewSubscriptionInvoiced and returns created true.
func (s *Store) RenewSubscriptionInvoicedOnce(orgID, id string, due, now time.Time, f func(*Subscription) error, inv Invoice) (Subscription, Invoice, bool, error) {
	if err := checkInvoice(inv); err != nil {
		return Subscription{}, Invoice{}, false, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.notDue(orgID, id, due, now) {
		return Subscription{}, Invoice{}, false, ErrNotDue
	}
	sub, err := s.nextSubscription(orgID, id, f)
	if err != nil {
		return Subscription{}, Invoice{}, false, err
	}
	existing, ok := s.invoiceForPeriod(inv.OrgID, inv.SubscriptionID, inv.PeriodStart)
	if ok {
		s.subs[id] = sub
		return copySub(sub), existing, false, nil
	}
	inv, err = s.createInvoice(inv, now)
	if err != nil {
		return Subscription{}, Invoice{}, false, err
	}
	s.subs[id] = sub
	return copySub(sub), inv, true, nil
}

