	if subID == "" || start == nil {
		return Invoice{}, false
	}
	for _, other := range s.invoices {
		if other.OrgID == orgID && other.SubscriptionID == subID && other.PeriodStart != nil && other.PeriodStart.Equal(*start) {
			return copyInvoice(other), true
		}
	}
	return Invoice{}, false
}

