// failingGateway fails charges to the payment method "pm_broken" with an error that is neither a decline nor an outage.
type failingGateway struct{ next payments.Gateway }

func (g failingGateway) Charge(ctx context.Context, req payments.ChargeRequest) (payments.ChargeResult, error) {
	if req.PaymentMethod == "pm_broken" {
		return payments.ChargeResult{}, errors.New("malformed gateway response")
	}
	return g.next.Charge(ctx, req)
}

func TestRenewDueGoesOnPastAnErrorAndReturnsIt(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	broken := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	healthy := e.CreateCustomer(e.Acme, "Joe", "joe@example.com")
	brokenSub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: broken.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	healthySub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: healthy.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, broken.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_broken"; return nil })
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, healthy.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
