293	// chargeInvoice charges an open invoice to the customer's default payment method. An invoice that needs no charge is marked
294	// paid; one whose customer has no payment method stays open and counts as paid here (it is paid by hand). It reports false
295	// when the charge was declined, and wraps payments.ErrUnavailable when the gateway could not take it.
296	func (s *Service) chargeInvoice(ctx context.Context, orgID, invoiceID string) (bool, error) {
